            ann='   <<WIDTH %d>>'%i.operands[1].imm
        elif i.mnemonic=='lea' and len(i.operands)>1 and i.operands[1].type==x86.X86_OP_MEM:
            mm=i.operands[1].mem
            ann='   <<DEST %s+%#x>>'%(i.reg_name(mm.base),mm.disp)
        elif i.mnemonic=='call':
            if i.operands[0].type==x86.X86_OP_MEM:
                ann='   <<STREAMCALL>>'
