                ann='   -><t>'
        elif i.mnemonic in ('je','jne','jz','jnz','jmp','jb','jae','jbe','ja','jl','jge','jle','jg','js','jns'):
            ann='   -><j>'
        out.append((o,t,ann))
        if stop_at_ret and i.mnemonic in ('ret','retn'): break
